{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Peramivir, a densely functionalized polar cyclopentane with amide and basic guanidine groups, has oral bioavailability <3% in humans, supporting low F for the similarly polar, sugar-bearing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Methysergide, an amide-containing basic amine, has systemic availability of 13% after oral dosing, supporting low F for the query's amide/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Perindoprilat, a polar ionizable molecule, has oral bioavailability of 19% ± 7% in young healthy subjects, near or below the 20% threshold, indicating that polar functionalized molecules like the query can be low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Delmopinol, a heterocyclic amine with hydroxyl groups, has very low oral bioavailability, consistent with the query's polar amine/sugar character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brivaracetam, a pyrrolidine amide with a propyl group, has ~100% oral bioavailability, but it lacks the query's polar sugar and chloride, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Perindopril, an ester prodrug, has ~75% oral bioavailability, but the query is not an ester prodrug and retains free hydroxyls.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query's polar thio-sugar, multiple hydroxyls, amide, and basic tertiary amine create high polar surface area and H-bond donor load, favoring poor permeability and low oral bioavailability. The most transferable experimental analogues (peramivir, methysergide, perindoprilat) show low or borderline F, while high-F analogues either lack the polar sugar (brivaracetam) or are ester prodrugs (perindopril).",
  "evidence_gaps": [
    "No direct oral bioavailability data for the query or a close analogue.",
    "Unknown intestinal permeability and transporter involvement for the query.",
    "Potential metabolic instability or reactivity of the chloroethyl group is not captured by the analogues.",
    "Lack of solubility and first-pass metabolism data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

